// Cloudflare Pages Function for the site root.
//
//   GET /?code=420          -> run.sh (text/x-sh, no-store)
//   GET /?code=123456789    -> aspot-bot.tar.gz (application/gzip + sha256 header)
//   GET /?code=<unknown>    -> 404 (never the homepage: it must not be piped to bash)
//   GET /<anything else>    -> the normal site
//
// The artefacts and the code -> file map are generated by hot_delivery.sh and
// deployed as static assets (aspot-bot/…), so publishing a new build is a git
// push, not a Worker deploy.  env.ASSETS is the binding Pages gives every
// Function; fetching through it serves the file from the current deployment and
// does not run the Function again (no extra invocation billed).
//
// `code` is branding, not a secret: it is printed in the doctor's shell history
// and inside run.sh.  Nothing here is access-controlled.

const MANIFEST_PATH = "/aspot-bot/manifest.json";

// Per-isolate memo: the manifest only changes when a new deployment is rolled
// out, and a fresh deployment gets fresh isolates.
let manifestPromise = null;

function loadManifest(env, request) {
  if (manifestPromise === null) {
    manifestPromise = (async () => {
      const response = await env.ASSETS.fetch(new URL(MANIFEST_PATH, request.url));
      if (!response.ok) return null;
      try {
        return await response.json();
      } catch {
        return null;  // a half-written manifest must not take the site down
      }
    })();
  }
  return manifestPromise;
}

function delivery(asset, entry) {
  const headers = new Headers();
  headers.set("content-type", entry.type || "application/octet-stream");
  headers.set("cache-control", entry.cache || "no-store");
  headers.set("x-robots-tag", "noindex, nofollow");
  headers.set("x-content-type-options", "nosniff");
  if (entry.disposition) headers.set("content-disposition", entry.disposition);
  if (entry.sha256) headers.set("x-aspot-bot-sha256", entry.sha256);
  return new Response(asset.body, { status: 200, headers });
}

export async function onRequest(context) {
  const { request, env, next } = context;
  const url = new URL(request.url);
  const code = url.searchParams.get("code");

  // Only the root answers to codes; every other path is an ordinary asset.
  if (url.pathname !== "/" || !code) return next();
  if (request.method !== "GET" && request.method !== "HEAD") return next();

  const manifest = await loadManifest(env, request);
  const entry = manifest?.entries?.[code];
  if (!entry) {
    // A code was given but it is not ours (typo, truncated paste).  Answer 404:
    // piping the homepage HTML into bash gives the doctor nonsense syntax errors.
    return new Response("aspot-bot: unknown code\n", {
      status: 404,
      headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" },
    });
  }

  let asset;
  try {
    asset = await env.ASSETS.fetch(new URL(entry.path, url));
  } catch {
    asset = null;  // a malformed manifest entry is a broken artefact, not a 500
  }
  if (!asset || !asset.ok) {
    return new Response("aspot-bot: brak artefaktu na tym wdrożeniu\n", {
      status: 503,
      headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" },
    });
  }
  return delivery(asset, entry);
}
